  "storage.creds.alsoUsedBy": "Ook gebruikt door",
  "signIns.title": "Inloggegevens",
  "signIns.hint": "De sleutels en wachtwoorden waarmee BombVault inlogt bij S3-diensten en restic REST-servers. Inloggegevens worden opgeslagen als je een bestemming toevoegt, en de standaard geldt overal waar niets gekozen is.",
  "signIns.default": "Standaard",
