  "signIns.windowHint": "Een wijziging geldt voor elke bestemming die deze inloggegevens gebruikt. „Testen” logt bij elk ervan in met wat je hebt getypt, zonder op te slaan.",
  "offsite.copies.title": "Offsite-kopieën",
  "rclone.paste": "Configuratie plakken",
  "whatsNew.signInMakeDefault": "Een ster markeert de standaard-inloggegevens, die overal gelden waar er geen gekozen zijn. „Als standaard” geeft de ster aan andere.",
  "whatsNew.signInEdit": "„Bewerken” opent inloggegevens in een venster, waar „Testen” ze vóór het opslaan probeert bij elke bestemming die ze gebruikt.",
  "whatsNew.gotItCheck": "Elke knop „Begrepen” heeft een vinkje.",
  "whatsNew.cardFoot": "Knoppen voor een hele kaart, zoals „Bestemming toevoegen”, staan aan het eind onder de inhoud van de kaart.",
  "whatsNew.memoryLimit": "Met een geheugenlimiet per back-up wordt een grote back-up trager in plaats van zonder geheugen te raken.",
  "whatsNew.instancesCardLogo": "Elke instantiekaart toont het logo op dezelfde plek en in dezelfde grootte, op de hoogte van de naam.",
  "whatsNew.instancesNetLogos": "In de afbeelding van de groep toont elke BombVault het logo met een klein badge dat een server van een telefoon onderscheidt.",
  "whatsNew.instancesCardSize": "Alle instantiekaarten zijn even breed en zo hoog als de hoogste.",
  "whatsNew.instancesFullNames": "Instantiekaarten tonen de hele naam. Badges schuiven onder een lange naam, en het soort instantie staat op een eigen regel.",
  "whatsNew.instancesNetLabels": "Namen in de afbeelding van de groep lopen door op meer regels in plaats van afgekapt te worden.",
  "whatsNew.instancesInactive": "Servers die uit staan en telefoons met de app gesloten houden hun kaart als Inactief, met wanneer ze het laatst gezien zijn, tot je ze verwijdert.",
  "whatsNew.instancesChecking": "Direct nadat BombVault gestart is, toont een kaart Controleren tot de instantie terug is, in plaats van verdwenen te lijken.",
  "whatsNew.pairingInactive": "De pagina Koppeling toont servers die uit staan en telefoons met de app gesloten als Inactief, met wanneer ze het laatst gezien zijn.",
  "whatsNew.settingsStorageFlow": "De instellingenpagina Bestemmingen toont ook welk onderdeel naar welke bestemming wordt geback-upt.",
  "whatsNew.addOwnRclone": "„Bestemming toevoegen” heeft een tegel Rclone voor je eigen rclone-configuratie, waar je remotes uit een rclone.conf plakt.",
  "whatsNew.cryptPicture": "De afbeelding bij versleuteling volgt haar schakelaar: verzegelde pakketten op de bestemming als back-ups versleuteld zijn, leesbare als ze dat niet zijn.",
  "whatsNew.providerLogos": "In „Bestemming toevoegen” tonen Amazon S3, Synology C2, Shade, 1Fichier, QingStor, Sia, FileLu, Drime en rclone hun logo, en elke tegel licht onder de aanwijzer op in de kleur van zijn merk. premiumize.me staat niet meer in de lijst, omdat het geen back-ups bewaart.",
  "whatsNew.settingsStorageList": "De instellingenpagina Bestemmingen toont alle bestemmingen. Met een klik open je er een.",
  "whatsNew.offsiteCopies": "De offsite-kopie van elk onderdeel is één rij in één kaart, met testen, repliceren en instellen op de rij. De rest opent in een venster.",
  "whatsNew.compressionRow": "De keuze voor compressie staat naast het label en is maar zo breed als de drie opties.",
  "whatsNew.localProtection": "Een lokale map toont de kaart Bescherming tegen verwijderen alleen als er een bescherming op staat die je kunt uitzetten.",
