  "whatsNew.signIns": "De gedeelde cloud-inloggegevens en de extra sets inloggegevens zijn één lijst, met één item als standaard. De lijst staat onder de bestemmingen en laat zien welke bestemmingen welk item gebruiken.",
  "whatsNew.locationSignIn": "Een bestemming kiest uit de opgeslagen inloggegevens, en „Bewerken” opent ze in hetzelfde venster als de instellingenpagina.",
  "whatsNew.ownFolderMove": "De eigen map van een onderdeel kan naar een van je bestemmingen verhuizen en neemt de inloggegevens en bescherming daarvan over. Meerdere onderdelen verhuizen in één stap.",
  "whatsNew.ownFoldersCard": "Een externe bestemming toont de onderdelen die er hun eigen back-ups bewaren.",
  "whatsNew.singleAction": "Als „Meer” maar één actie zou bevatten, staat die actie als eigen knop in beeld.",
