  "dbdump.toggle": "Databasedump voor elke back-up",
  "dbdump.toggleHint": "BombVault heeft deze container herkend als een {engine}-database. Voor elke back-up vraagt het de draaiende server om een volledige SQL-dump en legt die als eigen herstelpunt weg, rechtstreeks in de back-upopslag, zonder een bestand op je schijven te schrijven. Een herstel gebruikt de bestandsback-up die na het stoppen van de container is gemaakt; de dump is een tweede kopie die je kunt downloaden of importeren. Een mislukte dump laat de back-up nooit mislukken, hij verschijnt als een eigen mislukte uitvoering.",
  "dbdump.toggleHintLabel": "Het containerlabel bombvault.dbdump zet de dump aan voor deze {engine}-database. Voor elke back-up vraagt BombVault de draaiende server om een volledige SQL-dump en legt die als eigen herstelpunt weg. Een mislukte dump laat de back-up nooit mislukken, hij verschijnt als een eigen mislukte uitvoering.",
  "dbdump.toggleHintOnlyCopy": "Voor elke back-up vraagt BombVault deze draaiende {engine}-server om een volledige SQL-dump en legt die als eigen herstelpunt weg. Bij deze container is de dump de enige samenhangende kopie van de database: de gegevensmap wordt ofwel gekopieerd terwijl de server draait, ofwel zit in geen enkele back-up. Laat de dump aan staan. Een mislukte dump laat de back-up nooit mislukken, hij verschijnt als een eigen mislukte uitvoering.",
  "dbdump.toggleHintUnknown": "Voor elke back-up vraagt BombVault deze draaiende {engine}-server om een volledige SQL-dump en legt die als eigen herstelpunt weg. Waar deze container zijn gegevensmap bewaart, kon niet worden vastgesteld, dus is onbekend of de bestandsback-up een bruikbare kopie bevat. De dump is de kopie waarop je kunt rekenen. Laat hem aan staan. Een mislukte dump laat de back-up nooit mislukken, hij verschijnt als een eigen mislukte uitvoering.",
  "dbdump.lookalikeHint": "Deze container lijkt op een {engine}-database, maar BombVault kent zijn image niet zeker. Zet de dump aan als het er een is; mislukt hij daarna, dan volgt het image niet de gebruikelijke instellingen en kun je hem weer uitzetten.",
  "dbdump.engineLabel": "Databasetype",
  "dbdump.labelOff": "Uitgezet door het containerlabel bombvault.dbdump=false.",
  "dbdump.globalOff": "Automatische databasedumps staan voor alle containers uit in Instellingen, Algemeen.",
  "dbdump.offConfirmLive": "De dump voor deze database uitzetten? De gegevensmap wordt gekopieerd terwijl de server draait, dus zonder de dump bestaat er geen samenhangende kopie van.",
  "dbdump.offConfirmNone": "De dump voor deze database uitzetten? De gegevensmap zit in geen enkele back-up, dus zonder de dump wordt er niets van bewaard.",
  "dbdump.offConfirmUnknown": "De dump voor deze database uitzetten? BombVault kon niet vaststellen waar de gegevensmap staat, dus is onbekend of een back-up een bruikbare kopie bevat.",
  "dbdump.coverageStopped": "Gegevensmap: bewaard terwijl de container stilstaat.",
  "dbdump.coverageLive": "Gegevensmap: gekopieerd terwijl de server draait. De dump is de samenhangende kopie.",
  "dbdump.coverageNone": "Gegevensmap: in geen enkele back-up. De dump is de enige kopie.",
  "dbdump.coverageUnknown": "Gegevensmap: niet vast te stellen. Laat de dump aan staan.",
  "dbdump.coverageHint": "Een database schrijft voortdurend in zijn bestanden. Een kopie van die bestanden is alleen betrouwbaar als de server stilstaat terwijl ze wordt gemaakt, en dat doet BombVault voor mappen in de back-up van de container. Mappen in een compose-project of in een mappenset worden gekopieerd terwijl de server draait, en mappen buiten appdata worden helemaal niet gekopieerd. In die gevallen is de dump datgene waaruit je zou herstellen.",
  "dbdump.hookOverlap": "Het commando voor de back-up van deze container dumpt al een database. Zet er een van de twee uit, anders wordt de database twee keer gedumpt.",
  "dbdump.lastLine": "Laatste dump: {when}, {result}",
