  "dbdump.progress": "Database dumpen: {bytes}",
  "dbdump.busyDumping": "Database dumpen...",
  "dbdump.busySaving": "Databasedump opslaan...",
  "dbdump.busyImporting": "Databasedump importeren...",
  "dbdump.updateWarn": "Dit is een database. Een image-update kan hem naar een nieuwe hoofdversie brengen die de oude gegevensmap weigert. De dump van vlak voor de update kan dan vanuit het paneel Back-ups in de nieuwe versie worden geïmporteerd.",
  "dbdump.updateWarnSameMajor": "Dit is een database. Een image-update kan hem naar een nieuwe hoofdversie brengen. MySQL en MariaDB importeren een dump alleen in de hoofdversie waar hij vandaan komt, dus als de nieuwe versie de oude gegevensmap weigert, zet de image dan terug op de vorige versie en importeer daar de dump van vlak voor de update.",
  "dbdump.stackRestoreWarn": "one=De gegevens van {names} worden gekopieerd terwijl de stack draait. Importeer na het herstel de nieuwste databasedump ervan voordat je de app gebruikt.|other=De gegevens van {names} worden gekopieerd terwijl de stack draait. Importeer na het herstel hun nieuwste databasedump voordat je de apps gebruikt.",
  "dbdump.introNotice": "one=BombVault dumpt de databases die het herkent voor elke back-up, als eigen herstelpunten. Hier herkend: {n} database, {name}. Je kunt dit per container op zijn kaart uitzetten of voor alle containers in Instellingen.|other=BombVault dumpt de databases die het herkent voor elke back-up, als eigen herstelpunten. Hier herkend: {n} databases, de eerste is {name}. Je kunt dit per container op zijn kaart uitzetten of voor alle containers in Instellingen.",
  "dbdump.fixAuth": "Controleer de wachtwoordvariabelen op de databasecontainer zelf (bijvoorbeeld POSTGRES_PASSWORD, MARIADB_ROOT_PASSWORD of MYSQL_ROOT_PASSWORD, of hun _FILE-varianten). De dump gebruikt precies die.",
  "dbdump.fixPrivileges": "De dump kon alleen inloggen als de app-gebruiker, die een recht mist dat de dump nodig heeft. Geef de container een echt rootwachtwoord in plaats van een willekeurig.",
  "dbdump.fixUnreachable": "De databaseserver antwoordde niet op zijn lokale socket. Kijk in het log van de container, hij start misschien nog of is gecrasht.",
  "dbdump.fixNotRunning": "De container stond op pauze of was aan het herstarten toen de back-up liep. Blijft hij herstarten, kijk dan in zijn log.",
  "dbdump.fixNoClient": "Het image heeft geen dumpgereedschap. Gebruik het officiële image, of zet de dump voor deze container uit.",
  "dbdump.fixSecret": "Een wachtwoordbestand uit een _FILE-variabele kon door de gebruiker van de container niet worden gelezen. Controleer het pad en de rechten.",
  "dbdump.fixNoCredentials": "De containerinstellingen bevatten geen rootwachtwoord en geen gebruiker met een database. Stel MARIADB_ROOT_PASSWORD (of MYSQL_ROOT_PASSWORD) in, of een gebruiker en een database.",
  "dbdump.fixNeedsUpgrade": "De systeemtabellen van de database komen uit een oudere versie. Voeg de variabele MARIADB_AUTO_UPGRADE met waarde 1 toe aan de container en herstart hem, of voer mariadb-upgrade een keer in de container uit.",
  "dbdump.fixTimeout": "De dump liep tegen zijn tijdslimiet aan. Voeg voor een heel grote database de variabele DB_DUMP_MAX_HOURS toe aan de BombVault-container (Unraid: bewerk de container, Add another Path, Port, Variable), bijvoorbeeld 12.",
  "dbdump.fixBackupCap": "De hele back-up bereikte BACKUP_MAX_HOURS terwijl de dump liep. Verhoog BACKUP_MAX_HOURS op de BombVault-container.",
  "dbdump.fixStalled": "De dump kwam niet meer vooruit, meestal omdat de applicatie een slot vasthield. Hij wordt bij de volgende back-up opnieuw geprobeerd.",
  "dbdump.fixDumpData": "Het dumpgereedschap stopte met de getoonde melding. Het wordt bij de volgende back-up opnieuw geprobeerd; blijft het mislukken, dan noemt de melding de oorzaak.",
  "dbdump.fixDocker": "Docker heeft het dumpcommando niet uitgevoerd. Meestal werd de container gestopt, gepauzeerd of opnieuw gemaakt terwijl de back-up startte. Het wordt bij de volgende back-up opnieuw geprobeerd; blijft het gebeuren, controleer dan de Docker-service en de toegang van BombVault daartoe.",
  "dbdump.fixRepository": "De back-upopslag heeft de dump niet aangenomen, of minder bytes bewaard dan er gedumpt zijn. Controleer de opslag in Instellingen, Bestemmingen; de dump wordt bij de volgende back-up opnieuw geprobeerd.",
  "dbdump.fixLeftover": "Een beschadigde dump kon niet uit de opslag worden verwijderd. Verwijder hem uit de dumplijst in het paneel Back-ups.",
  "dbdump.fixHelper": "De dumphelper van BombVault eindigde zonder resultaat. Herhaalt dit zich, open dan een issue en voeg het diagnosepakket bij.",
  "dbdump.listTitle": "Databasedumps",
  "dbdump.listHint": "Elke dump is een volledige SQL-export die vlak voor de back-up uit de draaiende database wordt gehaald. BombVault laadt een dump nooit uit zichzelf terug: de container herstellen zet zijn bestanden terug, en zijn die opgeslagen terwijl de container stilstond, dan zijn dat de nieuwere kopie. Gebruik een dump wanneer die bestanden niet deugen: ze zijn gekopieerd terwijl de server draaide of helemaal niet, de database is naar een nieuwe hoofdversie gegaan, of de datamap is beschadigd. Importeren zet de dump in een pas gestarte, lege database en houdt de oude datamap ernaast. Een volledig .sql-bestand eindigt met een commentaarregel \"complete\".",
