  "dbdump.saveHint": "Schrijft de dump als bestand naar de gekozen map op de server, met nobody:users als eigenaar zodat je hem via de netwerkshare kunt openen. Het bestand bevat elke tabel en de wachtwoordhashes van de databasegebruikers; bewaar het waar alleen jij bij kunt.",
  "dbdump.saveCancelHint": "Annuleren stopt het opslaan en verwijdert het onafgemaakte bestand.",
  "dbdump.savedTo": "Opgeslagen in {path}",
  "dbdump.import": "Importeren in een verse database",
  "dbdump.importConfirm": "Deze {engine} {version}-dump in {container} importeren? BombVault stopt de container, zet zijn datamap opzij (die blijft behouden, er wordt niets verwijderd), start de container met een lege datamap en importeert de dump. De toepassingen die deze database gebruiken zien de stand van het moment van de dump.",
  "dbdump.importConfirmNoVersion": "Deze {engine}-dump in {container} importeren? BombVault stopt de container, zet zijn datamap opzij (die blijft behouden, er wordt niets verwijderd), start de container met een lege datamap en importeert de dump. De toepassingen die deze database gebruiken zien de stand van het moment van de dump.",
  "dbdump.importNoVersion": "Deze dump legt zijn databaseversie niet vast. Het importeren mislukt als de server hem niet kan lezen.",
  "dbdump.importStops": "one=Tijdens het importeren stopt BombVault ook {apps} en start die daarna weer. Mislukt het importeren nadat het begonnen is, dan blijven de oude gegevens apart staan en blijft de app gestopt.|other=Tijdens het importeren stopt BombVault ook deze apps: {apps}. Daarna starten ze weer. Mislukt het importeren nadat het begonnen is, dan blijven de oude gegevens apart staan en blijven de apps gestopt.",
  "dbdump.importDone": "Database geïmporteerd.",
  "dbdump.keptIncluded": "De kopie staat naast de gegevensmap, dus elke back-up of replica van de map of dataset erboven neemt hem mee. Verwijder hem zodra de database werkt.",
  "dbdump.removeKept": "Kopie verwijderen",
  "dbdump.keptRemoved": "De kopie is verwijderd.",
  "dbdump.importRefused.busy": "Er loopt al een andere back-up of herstelactie. Probeer het opnieuw zodra die klaar is.",
