  "dbdump.importRefused.version": "De server draait versie {server}, de dump komt uit {dump}. Gebruik voor dit importeren een image met versie {dump} of nieuwer.",
  "dbdump.importRefused.versionSameMajor": "De server draait versie {server}, de dump komt uit {dump}. MySQL en MariaDB importeren een dump alleen in de hoofdversie waar hij vandaan komt, dus gebruik voor dit importeren een image met versie {dump}.",
