  "dest.lock.none": "{name} kan verwijderen niet weigeren. Wie in je server komt, komt ook in deze offsite-repository. Tegen ransomware helpt een rest-server of een opslagdienst met Object Lock, bijvoorbeeld als tweede bestemming.",
