  "offsite.prune.title": "5 · Off-site prunen",
  "offsite.prune.info": "Deze stap meldt alleen wat er gebeurt, hij stelt niets in. Of deze kopie geprund wordt, bepalen append-only uit stap 4 en de bewaarwaarden bij Instellingen, Bestemmingen. Wil je een append-only-kopie toch prunen, voer dan restic forget --prune uit aan de opslagkant, ofwel volgens een eigen schema, ofwel door kort een tweede REST-server zonder append-only op te zetten, daardoorheen te prunen en hem weer af te sluiten.",
