  "mcp.title": "MCP-server",
  "mcp.statusLabel": "Status",
  "mcp.keysTitle": "Sleutels en aangemelde clients",
  "mcp.keysEmpty": "Nog geen sleutel. Verbind een client en BombVault maakt er een.",
  "mcp.details": "Details",
