  "instances.role.diff": "Bij een ontvanger verstuurt deze server: na elke back-up zet hij zijn offsite-kopie zelf op de andere instantie, en die laat daar niets verwijderen. Bij een ophaler haalt de andere instantie op: die leest de back-ups van deze server volgens haar eigen schema, en deze server kent noch haar bestemming noch haar inloggegevens. De ZFS-server neemt ZFS-replica's aan, blokgetrouwe kopieën van de datasets en geen back-ups.",
