  "anomaly.settings.title": "Anomalieën",
  "anomaly.settings.hint": "Vergelijkt elke back-up van een item met zijn eigen geschiedenis en meldt wat niet past. Draait na elke back-up op de achtergrond en vertraagt er geen. De meeste controles beginnen na 10 back-ups van een item; mislukkingen, het herschrijven van de meeste gegevens en een bijna lege bron worden vanaf het begin gecontroleerd. Vrije ruimte wordt bewaakt voor lokale repositories en voor rclone-repositories die haar doorgeven; op de gebruikersshare van Unraid is het de vrije ruimte van de hele array.",
  "anomaly.settings.toggle": "Anomalieën detecteren",
  "anomaly.settings.sensitivity": "Gevoeligheid",
  "anomaly.settings.sensitivityHint": "Streng meldt ook kleinere wijzigingen, Soepel alleen grote, Gebalanceerd past bij de meeste servers. Elk item kan een eigen instelling krijgen onder Anomalieën, Bewaking.",
  "anomaly.settings.notifyMin": "Een melding sturen voor",
  "anomaly.settings.notifyHint": "Gebruikt de kanalen die onder Meldingen zijn ingesteld. Elk item kan dit wijzigen onder Anomalieën, Bewaking. Herhaaldelijk mislukte back-ups en dumps en mislukte geplande herstelcontroles sturen al een eigen bericht en worden daarom niet nog eens gestuurd.",
  "anomaly.settings.notifyMuted": "Er wordt nu niets verstuurd: meldingen staan uit of er is geen kanaal ingesteld.",
  "anomaly.settings.openNotifications": "Meldingsinstellingen openen",
  "anomaly.settings.holdToggle": "Oude back-ups bewaren als een bron sterk krimpt of wordt herschreven",
  "anomaly.settings.holdHint": "Drie bevindingen zetten het verwijderen van oude back-ups stil: een bron die plotseling bijna leeg is, een die veel kleiner is geworden, en een back-up die de meeste gegevens opnieuw heeft opgeslagen, zoals ransomware eruitziet. Anders zou de bewaring de goede oudere back-ups één voor één verwijderen. Zolang zo'n anomalie open is, blijven de oude back-ups van alleen dat item (of die databasedump of die ZFS-dataset) bewaard; al het andere wordt zoals gewoonlijk opgeschoond. Bevestig de anomalie of markeer hem als verwacht om verder te gaan.",
